put('src/lib/game/storage.js','''export const keyForPuzzle=id=>`globs-session:${id}`;
const MAX_BYTES=4*1024*1024;
function bytes(raw){if(new TextEncoder().encode(raw).length>MAX_BYTES)throw new Error('Saved game exceeds the four MiB limit. Export before resetting.');}
export function readSession(id,storage=localStorage){const raw=storage.getItem(keyForPuzzle(id));if(raw===null)return {raw,saved:null};bytes(raw);let parsed;try{parsed=JSON.parse(raw);}catch{throw new Error('Saved game is unreadable. Its original bytes were preserved.');}if(parsed?.format===2){if(typeof parsed.generation!=='string'||!parsed.generation||!Number.isSafeInteger(parsed.revision)||parsed.revision<1)throw new Error('Saved game envelope is invalid.');return {raw,saved:parsed.snapshot};}return {raw,saved:parsed};}
const browserLock=(key,work)=>{if(!navigator.locks)throw new Error('Saving needs Web Locks on localhost or HTTPS.');return navigator.locks.request(key,work);};
export async function writeSession(id,snapshot,expectedRaw,storage=localStorage,lock=browserLock){const key=keyForPuzzle(id);return lock(key,()=>{const current=storage.getItem(key);if(current!==expectedRaw)throw new Error('Another tab changed this game. Export your pending move, then load the current game.');let previous;try{previous=current===null?null:JSON.parse(current);}catch{previous=null;}const revision=previous?.format===2?previous.revision+1:1;if(!Number.isSafeInteger(revision))throw new Error('Saved game revision is exhausted.');const raw=JSON.stringify({format:2,generation:previous?.format===2?previous.generation:crypto.randomUUID(),revision,snapshot});bytes(raw);storage.setItem(key,raw);return raw;});}
export async function resetSession(id,snapshot,expectedRaw,storage=localStorage,lock=browserLock){const key=keyForPuzzle(id);return lock(key,()=>{if(storage.getItem(key)!==expectedRaw)throw new Error('Saved game changed while reset was open. Review it before resetting.');const raw=JSON.stringify({format:2,generation:crypto.randomUUID(),revision:1,snapshot});bytes(raw);storage.setItem(key,raw);return raw;});}
''')
